import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// Font Loader Hook
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type CreditCardThrowProps = Record<string, any>;

const CreditCardThrow: React.FC<CreditCardThrowProps> = ({
  backgroundColor = "#f0f0f0",
  transparentBackground = false,
  durationInSeconds = 6,
  cardColors = ["#1a1f71", "#000000", "#c62828"],
  throwHeight = 0.6,
  cardScale = 1.0,
}) => {
  useFontLoader(["Inter", "Roboto Mono"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Constants & Calculations ---
  const totalFrames = durationInSeconds * fps;
  const throwCount = 3;
  // Calculate frames per throw to fit exactly into duration
  const framesPerThrow = Math.floor(totalFrames / throwCount);

  // Determine current cycle
  const currentThrowIndex = Math.floor(frame / framesPerThrow);
  
  // Local frame time within the current throw (0 to framesPerThrow)
  const localFrame = frame % framesPerThrow;

  // Active Color
  const safeColorIndex = Math.min(currentThrowIndex, cardColors.length - 1) >= 0 
    ? Math.min(currentThrowIndex, cardColors.length - 1)
    : 0; // Fallback
    
  // Cycle through colors if we have enough, or clamp if we run out? 
  // Request says "changes to a different color on each throw".
  // We'll use modulo if user provides fewer colors than throws, or clamp.
  // Let's use modulo to be safe for infinite looping logic, but here we have 3 throws fixed.
  const activeCardColor = cardColors[currentThrowIndex % cardColors.length] || "#1a1f71";

  // --- Animation Physics ---
  const halfDuration = framesPerThrow / 2;
  const startY = height + 300; // Off-screen bottom
  const peakY = height * (1 - throwHeight); // Target height (e.g. 40% from top)

  // 1. Upward Motion (Decelerate)
  const upY = interpolate(
    localFrame,
    [0, halfDuration],
    [startY, peakY],
    {
      easing: Easing.out(Easing.quad), // Decelerate as it goes up (Gravity)
      extrapolateRight: "clamp",
    }
  );

  // 2. Downward Motion (Accelerate)
  const downY = interpolate(
    localFrame,
    [halfDuration, framesPerThrow],
    [peakY, startY],
    {
      easing: Easing.in(Easing.quad), // Accelerate as it falls (Gravity)
      extrapolateLeft: "clamp",
    }
  );

  // Combine motions
  const currentY = localFrame < halfDuration ? upY : downY;

  // Rotation: Subtle spin during throw
  const rotateZ = interpolate(
    localFrame,
    [0, framesPerThrow],
    [-15, 15], // Rotates from -15deg to 15deg during the arc
    { extrapolateRight: "clamp" }
  );
  
  // Scale: slight punch at apex? No, constant scale is better for physics realism,
  // but maybe a tiny bit of perspective scaling if we assume it moves in Z?
  // Let's keep it simple 2D as requested.

  // --- Styles ---
  const bg = transparentBackground ? "transparent" : backgroundColor;
  
  // Card Dimensions (Standard Ratio 1.586)
  const cardW = 500 * cardScale;
  const cardH = 315 * cardScale;
  const borderRadius = 20 * cardScale;
  
  // Don't render if we've exceeded the throw count
  if (currentThrowIndex >= throwCount) {
    return <AbsoluteFill style={{ backgroundColor: bg }} />;
  }

  return (
    <AbsoluteFill style={{ backgroundColor: bg, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: (width - cardW) / 2,
          top: currentY,
          width: cardW,
          height: cardH,
          backgroundColor: activeCardColor,
          borderRadius: borderRadius,
          transform: `rotate(${rotateZ}deg)`,
          boxShadow: "0 20px 40px rgba(0,0,0,0.3)",
          display: "flex",
          flexDirection: "column",
          padding: `${25 * cardScale}px`,
          boxSizing: "border-box",
          fontFamily: "Inter, sans-serif",
          color: "white",
        }}
      >
        {/* Top Row */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", width: "100%" }}>
          {/* Chip / Number */}
          <div style={{ display: "flex", flexDirection: "column", gap: 10 * cardScale }}>
            {/* Fake Chip */}
            <div
              style={{
                width: 50 * cardScale,
                height: 40 * cardScale,
                background: "linear-gradient(135deg, #e0e0e0 0%, #bdbdbd 100%)",
                borderRadius: 6 * cardScale,
                position: "relative",
                overflow: "hidden",
              }}
            >
               <div style={{ position: "absolute", top: "50%", left: 0, right: 0, height: 1, background: "#999" }} />
               <div style={{ position: "absolute", left: "30%", top: 0, bottom: 0, width: 1, background: "#999" }} />
               <div style={{ position: "absolute", left: "70%", top: 0, bottom: 0, width: 1, background: "#999" }} />
            </div>

            {/* Masked Number */}
            <div style={{ 
                fontFamily: "Roboto Mono, monospace", 
                fontSize: 18 * cardScale, 
                opacity: 0.8,
                marginTop: 10 * cardScale,
                letterSpacing: 2
            }}>
              •••• 3346
            </div>
          </div>

          {/* VISA Logo Recreation */}
          <div style={{ 
             fontSize: 32 * cardScale, 
             fontWeight: 900, 
             fontStyle: "italic", 
             fontFamily: "Inter, sans-serif",
             letterSpacing: -1,
             position: "relative"
          }}>
            <span style={{ color: "white" }}>VISA</span>
            {/* Simple tick mark for logo styling */}
            <div style={{
                position: "absolute",
                top: 0,
                left: -5 * cardScale,
                width: 15 * cardScale,
                height: 5 * cardScale,
                background: "white",
                transform: "rotate(-45deg)",
                opacity: 0 // Just using text for simplicity as requested "do not reference image"
            }}/> 
          </div>
        </div>

        {/* Bottom Row - Large Brand Text */}
        <div style={{ 
            marginTop: "auto", 
            fontSize: 70 * cardScale, 
            fontWeight: 700,
            letterSpacing: -2,
        }}>
          MALLOY
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CreditCardThrow;